import { createHash } from "node:crypto";
import type { ChatMessage, ToolDefinition } from "../types.js";
import type { UsageReport } from "../usage.js";

/** Why a native response ended. "length" is never a complete answer; "incomplete" means no terminal event arrived. */
export type NativeFinish = "stop" | "tool_calls" | "length" | "refusal" | "incomplete";

export interface NativeResult {
  message: ChatMessage;
  finish: NativeFinish;
  usage?: UsageReport;
  providerRequestId?: string;
  effectiveModel?: string;
  /** Visible text received, for failure reporting. */
  text: string;
  /** The provider's own finish_reason, where the protocol has one (openai-chat). */
  finishReason?: string;
}

export interface NativeRequestInput {
  model: string;
  messages: ChatMessage[];
  tools: ToolDefinition[];
  temperature?: number;
  maxOutputTokens: number;
  stream: boolean;
  /** "<provider>:<model>": only provider_state with this owner is replayed. */
  owner: string;
  reasoningEffort?: string;
  thinkingBudget?: number;
  /** openai-chat only. */
  chat?: { toolChoice: "auto" | "required"; capOutput: boolean; usage: "openrouter" | "stream-options" | "native" | "none" };
}

export interface NativeRequest {
  path: string;
  body: Record<string, unknown>;
  /** Assistant turns whose foreign or altered opaque state was not replayed (explicit rebase). */
  droppedState: number;
}

/** A provider-reported error inside a stream (or an unusable stream). The client maps it to an InferenceError. */
export class ProviderStreamError extends Error {
  constructor(
    message: string,
    readonly errorType: string | undefined,
    readonly partialText: string,
    readonly malformed = false,
  ) {
    super(message);
    this.name = "ProviderStreamError";
  }
}

export interface StreamParser {
  /** One SSE event: `event:` name (if any) and the parsed `data:` JSON. */
  event(name: string | undefined, data: any): void;
  /** The assembled result; finish is "incomplete" when the terminal event never arrived. */
  result(): NativeResult;
  text(): string;
}

/**
 * Reads an SSE body, handing each complete event to `onEvent`. Handles CRLF, comments/heartbeats, multi-line data and
 * events split at any byte (including inside UTF-8 sequences). `[DONE]` sentinels are ignored.
 */
export async function readSse(
  body: ReadableStream<Uint8Array>,
  onEvent: (name: string | undefined, data: string) => void,
  onChunk?: () => void,
): Promise<void> {
  const reader = body.getReader();
  const decoder = new TextDecoder("utf-8");
  let buffer = "";
  let name: string | undefined;
  let data: string[] = [];
  const dispatch = () => {
    if (data.length) {
      const joined = data.join("\n");
      if (joined.trim() !== "[DONE]") onEvent(name, joined);
    }
    name = undefined;
    data = [];
  };
  const line = (raw: string) => {
    const l = raw.endsWith("\r") ? raw.slice(0, -1) : raw;
    if (l === "") return dispatch();
    if (l.startsWith(":")) return;
    const colon = l.indexOf(":");
    const field = colon < 0 ? l : l.slice(0, colon);
    let value = colon < 0 ? "" : l.slice(colon + 1);
    if (value.startsWith(" ")) value = value.slice(1);
    if (field === "event") name = value;
    else if (field === "data") data.push(value);
  };
  try {
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      onChunk?.();
      buffer += decoder.decode(value, { stream: true });
      const lines = buffer.split("\n");
      buffer = lines.pop() ?? "";
      for (const l of lines) line(l);
    }
    buffer += decoder.decode();
    if (buffer) line(buffer);
    dispatch();
  } catch (err) {
    try { await reader.cancel(); } catch {}
    throw err;
  }
}

export function stateDigest(items: unknown[]): string {
  return createHash("sha256").update(JSON.stringify(items)).digest("hex");
}

/** Opaque state replayable to `owner`: same owner and unaltered since capture. */
export function ownedState(m: ChatMessage, owner: string): any[] | undefined {
  const s = m.provider_state;
  if (!s || s.owner !== owner || !Array.isArray(s.items)) return undefined;
  return stateDigest(s.items) === s.digest ? s.items : undefined;
}

/** Tool ids must match ^[A-Za-z0-9_-]+$ for Anthropic; the mapping is deterministic so calls and results still pair. */
export function wireToolId(id: string): string {
  const clean = (id || "call").replace(/[^A-Za-z0-9_-]/g, "_");
  return clean.slice(0, 64) || "call";
}

export function textOf(content: ChatMessage["content"]): string {
  if (typeof content === "string") return content;
  if (Array.isArray(content)) {
    return content.map((p: any) => (typeof p === "string" ? p : p?.type === "text" ? p.text ?? "" : "")).join("");
  }
  return "";
}

/** Tool-call arguments as an object for protocols that take structured input; malformed text is preserved as {raw}. */
export function argumentsObject(args: string | undefined): Record<string, unknown> {
  try {
    const v = JSON.parse(args || "{}");
    return v && typeof v === "object" && !Array.isArray(v) ? v : { value: v };
  } catch {
    return { raw: args };
  }
}

export function num(v: unknown): number | undefined {
  return typeof v === "number" && Number.isFinite(v) ? v : undefined;
}
/** The wire protocols a connection can speak. Adding one is a module here plus an entry in WIRE_PROTOCOLS. */
import type { WireProtocol } from "../providers.js";
import { anthropicStreamParser, buildAnthropicRequest, parseAnthropicResponse } from "./anthropic.js";
import type { NativeRequest, NativeRequestInput, NativeResult, StreamParser } from "./common.js";
import { buildChatRequest, chatStreamParser, parseChatResponse } from "./openai_chat.js";
import { buildResponsesRequest, parseResponsesResponse, responsesStreamParser } from "./openai_responses.js";

export interface ProtocolAdapter {
  /** Served by the client's shared native request path; false means the client's own chat pipeline. */
  native: boolean;
  /** Tool calling is part of the protocol (otherwise a server may reject `tools`). */
  nativeTools: boolean;
  build(input: NativeRequestInput): NativeRequest;
  parse(data: any, owner: string, keepReasoning: boolean): NativeResult;
  stream(owner: string, keepReasoning: boolean, onToken?: (t: string) => void): StreamParser;
}

export const WIRE_PROTOCOLS: Record<WireProtocol, ProtocolAdapter> = {
  "openai-chat": {
    native: false,
    nativeTools: false,
    build: buildChatRequest,
    // Chat responses carry no provider state: owner and keepReasoning are ignored.
    parse: (data) => parseChatResponse(data),
    // Likewise ignored here; reasoning text is always kept on the message.
    stream: (_owner, _keepReasoning, onToken) => chatStreamParser(onToken),
  },
  "openai-responses": {
    native: true,
    nativeTools: true,
    build: buildResponsesRequest,
    parse: parseResponsesResponse,
    stream: responsesStreamParser,
  },
  "anthropic-messages": {
    native: true,
    nativeTools: true,
    build: buildAnthropicRequest,
    parse: (data, owner) => parseAnthropicResponse(data, owner),
    stream: (owner, _keepReasoning, onToken) => anthropicStreamParser(owner, onToken),
  },
};

export function wireProtocol(name: string): ProtocolAdapter {
  const adapter = (WIRE_PROTOCOLS as Record<string, ProtocolAdapter | undefined>)[name];
  if (!adapter) throw new Error(`unknown wire protocol: ${name}`);
  return adapter;
}
/**
 * Anthropic Messages API: request projection from Nexus history and assembly of streamed/non-streamed responses.
 *
 * Tool calls are emitted only from complete tool_use blocks of a response that reached message_stop; a stream that
 * ends earlier is "incomplete" and none of its calls run. Signed thinking blocks are kept as provider_state owned by
 * "anthropic:<model>" and replayed only to that owner, and only when extended thinking is enabled for the request.
 */
import type { ChatMessage, ToolCall } from "../types.js";
import type { UsageReport } from "../usage.js";
import {
  argumentsObject,
  num,
  ownedState,
  ProviderStreamError,
  stateDigest,
  textOf,
  wireToolId,
  type NativeFinish,
  type NativeRequest,
  type NativeRequestInput,
  type NativeResult,
  type StreamParser,
} from "./common.js";

type Block = Record<string, any>;
interface Turn { role: "user" | "assistant"; content: Block[] }

function userBlocks(content: ChatMessage["content"]): Block[] {
  if (!Array.isArray(content)) {
    const t = textOf(content);
    return t ? [{ type: "text", text: t }] : [];
  }
  const out: Block[] = [];
  for (const p of content as any[]) {
    if (typeof p === "string") out.push({ type: "text", text: p });
    else if (p?.type === "text" && p.text) out.push({ type: "text", text: p.text });
    else if (p?.type === "image_url" && typeof p.image_url?.url === "string") {
      const m = /^data:([^;]+);base64,(.*)$/s.exec(p.image_url.url);
      out.push(m ? { type: "image", source: { type: "base64", media_type: m[1], data: m[2] } } : { type: "image", source: { type: "url", url: p.image_url.url } });
    }
  }
  return out;
}

/** Thinking is replayable only when the trailing assistant tool turn carries this owner's intact signed thinking. */
function trailingToolTurnHasThinking(messages: ChatMessage[], owner: string): boolean {
  for (let i = messages.length - 1; i >= 0; i--) {
    const m = messages[i];
    if (m.role === "tool") continue;
    if (m.role === "assistant" && m.tool_calls?.length) return Boolean(ownedState(m, owner)?.length);
    return true; // not inside a tool loop: thinking may start fresh
  }
  return true;
}

export function buildAnthropicRequest(input: NativeRequestInput): NativeRequest {
  const thinking = input.thinkingBudget !== undefined && trailingToolTurnHasThinking(input.messages, input.owner);
  const systemParts: string[] = [];
  const turns: Turn[] = [];
  let droppedState = 0;
  let seenNonSystem = false;
  const push = (role: Turn["role"], blocks: Block[]) => {
    if (!blocks.length) return;
    const last = turns[turns.length - 1];
    if (last && last.role === role) last.content.push(...blocks);
    else turns.push({ role, content: blocks });
  };
  for (const m of input.messages) {
    if (m.role === "system") {
      const t = textOf(m.content);
      if (!seenNonSystem) systemParts.push(t);
      else if (t) push("user", [{ type: "text", text: `[System notice]\n${t}` }]);
      continue;
    }
    seenNonSystem = true;
    if (m.role === "user") push("user", userBlocks(m.content));
    else if (m.role === "tool") {
      const content = typeof m.content === "string" ? m.content : JSON.stringify(m.content ?? "");
      push("user", [{ type: "tool_result", tool_use_id: wireToolId(m.tool_call_id ?? ""), content: content || "(no output)" }]);
    } else {
      const blocks: Block[] = [];
      const owned = ownedState(m, input.owner);
      if (m.provider_state && !owned) droppedState++;
      if (thinking && owned) blocks.push(...owned);
      const t = textOf(m.content);
      if (t.trim()) blocks.push({ type: "text", text: t });
      for (const tc of m.tool_calls ?? []) {
        blocks.push({ type: "tool_use", id: wireToolId(tc.id), name: tc.function.name, input: argumentsObject(tc.function.arguments) });
      }
      push("assistant", blocks.length ? blocks : [{ type: "text", text: "(no content)" }]);
    }
  }
  if (turns[0]?.role !== "user") turns.unshift({ role: "user", content: [{ type: "text", text: "(continue)" }] });

  const body: Record<string, unknown> = {
    model: input.model,
    max_tokens: input.maxOutputTokens,
    messages: turns,
    stream: input.stream,
  };
  const system = systemParts.filter(Boolean).join("\n\n");
  if (system) body.system = system;
  if (input.tools.length) {
    body.tools = input.tools.map((t) => ({ name: t.function.name, description: t.function.description, input_schema: t.function.parameters }));
  }
  if (thinking) {
    // Extended thinking requires max_tokens above the budget and does not accept a custom temperature.
    const budget = Math.max(1024, Math.min(input.thinkingBudget!, input.maxOutputTokens - 1024));
    body.thinking = { type: "enabled", budget_tokens: budget };
    if (input.maxOutputTokens <= budget) body.max_tokens = budget + 1024;
  } else if (input.temperature !== undefined) {
    body.temperature = Math.min(1, Math.max(0, input.temperature));
  }
  return { path: "/messages", body, droppedState };
}

function finishOf(stop: string | undefined, hasTools: boolean): NativeFinish {
  if (stop === "max_tokens" || stop === "model_context_window_exceeded") return "length";
  if (stop === "refusal") return "refusal";
  if (stop === "tool_use" || hasTools) return "tool_calls";
  return "stop";
}

function usageOf(u: any, prev: UsageReport = {}): UsageReport {
  if (!u || typeof u !== "object") return prev;
  return {
    ...prev,
    ...(num(u.input_tokens) !== undefined ? { inputTokens: u.input_tokens } : {}),
    ...(num(u.output_tokens) !== undefined ? { outputTokens: u.output_tokens } : {}),
    ...(num(u.cache_read_input_tokens) !== undefined ? { cachedInputTokens: u.cache_read_input_tokens } : {}),
    ...(num(u.cache_creation_input_tokens) !== undefined ? { cacheWriteTokens: u.cache_creation_input_tokens } : {}),
  };
}

function assemble(blocks: Block[], stop: string | undefined, owner: string, usage: UsageReport | undefined, id?: string, model?: string): NativeResult {
  let text = "";
  const toolCalls: ToolCall[] = [];
  const opaque: Block[] = [];
  for (const b of blocks) {
    if (b.type === "text") text += b.text ?? "";
    else if (b.type === "tool_use") {
      const args = typeof b.input === "object" && b.input !== null ? JSON.stringify(b.input) : (b.json || "{}");
      toolCalls.push({ id: b.id, type: "function", function: { name: b.name, arguments: args } });
    } else if (b.type === "thinking") opaque.push({ type: "thinking", thinking: b.thinking ?? "", signature: b.signature ?? "" });
    else if (b.type === "redacted_thinking") opaque.push({ type: "redacted_thinking", data: b.data });
  }
  const message: ChatMessage = {
    role: "assistant",
    content: text || null,
    ...(toolCalls.length ? { tool_calls: toolCalls } : {}),
    ...(opaque.length ? { provider_state: { owner, items: opaque, digest: stateDigest(opaque) } } : {}),
  };
  return { message, finish: finishOf(stop, toolCalls.length > 0), usage, providerRequestId: id, effectiveModel: model, text };
}

export function parseAnthropicResponse(data: any, owner: string): NativeResult {
  if (!data || !Array.isArray(data.content)) throw new ProviderStreamError("Anthropic response has no content array", undefined, "", true);
  return assemble(data.content, data.stop_reason, owner, usageOf(data.usage), data.id, data.model);
}

export function anthropicStreamParser(owner: string, onToken?: (t: string) => void): StreamParser {
  const blocks: Block[] = [];
  const open = new Set<number>();
  let stop: string | undefined;
  let stopped = false;
  let usage: UsageReport | undefined;
  let id: string | undefined;
  let model: string | undefined;
  let text = "";
  return {
    text: () => text,
    event(_name, ev) {
      switch (ev?.type) {
        case "message_start":
          id = ev.message?.id;
          model = ev.message?.model;
          usage = usageOf(ev.message?.usage);
          return;
        case "content_block_start": {
          const cb = { ...(ev.content_block ?? {}) };
          if (cb.type === "tool_use") { cb.json = ""; delete cb.input; }
          if (cb.type === "thinking") { cb.thinking ??= ""; cb.signature ??= ""; }
          if (cb.type === "text") cb.text ??= "";
          blocks[ev.index] = cb;
          open.add(ev.index);
          return;
        }
        case "content_block_delta": {
          const b = blocks[ev.index];
          const d = ev.delta ?? {};
          if (!b) throw new ProviderStreamError(`content_block_delta for unknown block ${ev.index}`, undefined, text, true);
          if (d.type === "text_delta") {
            b.text += d.text ?? "";
            text += d.text ?? "";
            if (d.text) onToken?.(d.text);
          } else if (d.type === "input_json_delta") b.json += d.partial_json ?? "";
          else if (d.type === "thinking_delta") b.thinking += d.thinking ?? "";
          else if (d.type === "signature_delta") b.signature += d.signature ?? "";
          return;
        }
        case "content_block_stop":
          open.delete(ev.index);
          return;
        case "message_delta":
          if (ev.delta?.stop_reason) stop = ev.delta.stop_reason;
          usage = usageOf(ev.usage, usage);
          return;
        case "message_stop":
          stopped = true;
          return;
        case "error":
          throw new ProviderStreamError(`Provider error frame mid-stream: ${ev.error?.message ?? JSON.stringify(ev.error)}`, ev.error?.type, text);
        default:
          return; // ping and future event types
      }
    },
    result() {
      if (!stopped || open.size > 0) {
        return { message: { role: "assistant", content: text || null }, finish: "incomplete", usage, providerRequestId: id, effectiveModel: model, text };
      }
      for (const b of blocks) {
        if (b?.type === "tool_use") {
          try {
            b.input = JSON.parse(b.json || "{}");
          } catch {
            b.input = undefined; // kept as raw text; the agent's parser reports malformed arguments, nothing runs on a guess
          }
        }
      }
      return assemble(blocks.filter(Boolean), stop, owner, usage, id, model);
    },
  };
}
/**
 * Cloud inference providers: one declaration per provider feeds configuration, credential scoping, disclosure policy
 * and request construction. The local appliance is not a provider here: a configuration without a provider id keeps
 * the original endpoint path (LOCAL_LLM_*, stored gateway token, X-Task-Class, endpoint failover) unchanged.
 *
 * Separate concepts:
 * - Provider definition (PROVIDERS): identity, wire protocol, default base URL, credential variable, auth style.
 * - Connection (ResolvedConnection): the base URL actually used, its credential scope and disclosure class.
 * - Model: the provider's model id, passed verbatim (ids may contain "/" and ":").
 * - Role binding: main, planner and coder each name their own provider; subagents and auxiliary calls inherit main.
 */
